pages={
'premium':('Premium Hub','Premium command center for wallet, passes, officers, and services.', ['Open Store','Claim daily premium','Review transaction history'], ['premium_purchase','premium_claim_daily','premium_activate'], ['premium_catalog','player_premium','premium_transactions','game_events'], ['wallet summary','season pass progression','officer status','service credits']),
'store':('Premium Store','Purchase non-pay-to-win convenience services and season rewards with Dark Matter.', ['Buy item','Inspect catalogue','Review purchases'], ['premium_purchase'], ['premium_catalog','player_premium','premium_transactions'], ['catalogue pricing','purchase validation','transaction history','balance telemetry']),
'commander':('Commander','Manage the commander premium profile, daily claim, and season pass progression.', ['Claim daily reward','Activate season pass','Refresh profile'], ['premium_claim_daily','premium_activate'], ['player_premium','premium_transactions','game_events'], ['daily claim cooldown','season pass state','season points','wallet balance']),
'premium-officers':('Premium Officers','Activate time-limited officers with transparent modifiers and expiry tracking.', ['Activate officer','Inspect effects','Refresh officer status'], ['premium_activate'], ['premium_catalog','player_premium','premium_transactions'], ['officer roster','effect modifiers','expiry state','activation history']),
'premium-services':('Premium Services','Consume bounded convenience services such as queue priority and colony scan credits.', ['Activate service','Inspect service credits','Refresh services'], ['premium_activate'], ['premium_catalog','player_premium','premium_transactions'], ['service catalogue','credit balances','cooldown state','audit history']),
}
for route,(title,purpose,controls,actions,tables,details) in pages.items():
    slug=route
    pdef=f"""<?php\nreturn {repr({'route':route,'group':'premium','group_label':'Premium','title':title,'layout':'dashboard','controls':controls,'actions':actions,'tables':tables,'details':details,'interaction':{'server_authoritative':True,'feedback_states':['ready','empty','cooldown','insufficient-resource','success','error']},'logic':{'purpose':purpose,'workflow':['load wallet and catalogue','validate authentication, CSRF, ownership, price, quantity, and cooldown','lock wallet rows and commit transaction','render updated state and feedback'],'validation':['authenticated commander','server-side catalogue item','wallet row lock','positive bounded quantity','cooldown and ownership checks'],'calculations':['purchase cost = catalogue price × quantity','season progression = claimed rewards + validated activity','service effect = catalogue effect × active duration'],'mutations':['premium wallet debit or reward credit','officer/service activation','transaction audit event']},'features':['wallet telemetry','server-validated controls','transaction history','feedback states']})};\n"""
    logic=f"""<?php\nreturn {repr({'purpose':purpose,'workflow':['load wallet and catalogue','validate intent','lock and mutate transactionally','render result'],'validation':['authenticated commander','CSRF token','catalogue ownership and active status','wallet balance','cooldown and quantity bounds'],'calculations':['purchase cost = price × quantity','daily reward = 100 Dark Matter once per 24 hours','officer effect = catalogue modifier while active'],'mutations':['premium wallet update','premium transaction audit','game event emission']})};\n"""
    features=f"<?php\nreturn {repr(['Premium wallet and Dark Matter balance','Season pass and daily claim tracking','Officer effect and expiry telemetry','Bounded service credits','Purchase and activation audit history','Responsive dashboard controls'])};\n"
    design=f"<?php\nreturn {repr({'template':'premium-dashboard','sections':['wallet header','premium catalogue','active effects','transaction history','server contract','feedback'],'components':['metric-strip','catalogue-table','effect-badges','action-controls','audit-table','status-badge'],'responsive':'stacked mobile layout','theme':'inherits Default White, Window Blue Sci-Fi, and Deep Space Blue tokens'})};\n"
    systems=f"<?php\nreturn {repr({'services':['PremiumService'],'reads':tables,'writes':['player_premium','premium_transactions','game_events'],'actions':actions,'feedback_states':['ready','empty','cooldown','insufficient-resource','success','error'],'security':['authentication','CSRF','server-side price lookup','transaction row locks','ownership and cooldown validation']})};\n"
    for directory,content in [('page_definitions',pdef),('page_logic',logic),('page_features',features),('page_design_specs',design),('page_systems',systems)]:
        (root/'config'/directory/'premium').mkdir(parents=True,exist_ok=True)
        (root/'config'/directory/'premium'/f'{route}.php').write_text(content)
    module=f"""<?php\ndeclare(strict_types=1);\nfunction stargatewars_premium_{slug.replace('-','_')}_logic(): array {{ return require '/home/ubuntu/stargatewars/config/page_logic/premium/{route}.php'; }}\nfunction stargatewars_premium_{slug.replace('-','_')}_features(): array {{ return require '/home/ubuntu/stargatewars/config/page_features/premium/{route}.php'; }}\nfunction stargatewars_premium_{slug.replace('-','_')}_design(): array {{ return require '/home/ubuntu/stargatewars/config/page_design_specs/premium/{route}.php'; }}\nfunction stargatewars_premium_{slug.replace('-','_')}_systems(): array {{ return require '/home/ubuntu/stargatewars/config/page_systems/premium/{route}.php'; }}\nfunction stargatewars_premium_{slug.replace('-','_')}_actions(): array {{ return stargatewars_premium_{slug.replace('-','_')}_systems()['actions'] ?? []; }}\nfunction stargatewars_premium_{slug.replace('-','_')}_validate_intent(array $input): array {{\n $errors=[]; $action=(string)($input['action']??''); if($action===''||!in_array($action,stargatewars_premium_{slug.replace('-','_')}_actions(),true)) $errors['action']='Action is not permitted for this Premium page.';\n if(isset($input['quantity']) && ((int)$input['quantity']<1||(int)$input['quantity']>10)) $errors['quantity']='Quantity must be between 1 and 10.';\n return ['valid'=>$errors===[],'errors'=>$errors,'action'=>$action];\n}}\nfunction stargatewars_premium_{slug.replace('-','_')}_preview(array $context=[]): array {{ return ['route'=>'{route}','title'=>'{title}','logic'=>stargatewars_premium_{slug.replace('-','_')}_logic(),'features'=>stargatewars_premium_{slug.replace('-','_')}_features(),'design'=>stargatewars_premium_{slug.replace('-','_')}_design(),'systems'=>stargatewars_premium_{slug.replace('-','_')}_systems(),'context'=>$context]; }}\n"""
    (root/'includes/page_modules/premium'/f'{route}.php').write_text(module)

