if "PremiumService.php" not in text: text=text.replace("require_once __DIR__ . '/../includes/services/SettlementConstructionService.php';", "require_once __DIR__ . '/../includes/services/SettlementConstructionService.php';\nrequire_once __DIR__ . '/../includes/services/PremiumService.php';")
