insert="""        case 'premium_purchase': $premium=(new PremiumService(db()))->purchase((int)$user['id'],trim((string)$_POST['item_key']),(int)($_POST['quantity']??1)); $_SESSION['premium_state']=$premium; $_SESSION['flash']='Premium purchase completed.'; break;\n        case 'premium_claim_daily': $premium=(new PremiumService(db()))->claimDaily((int)$user['id']); $_SESSION['premium_state']=$premium; $_SESSION['flash']='Daily premium reward claimed: '.number_format((int)$premium['reward']).' Dark Matter.'; break;\n        case 'premium_activate': $premium=(new PremiumService(db()))->activate((int)$user['id'],trim((string)$_POST['item_key'])); $_SESSION['premium_state']=$premium; $_SESSION['flash']='Premium item activated.'; break;\n"""
