# Add a themed Premium dashboard renderer and route dispatch to the SPA.
g=root/'game.php'; gt=g.read_text()
if 'function premiumPage()' not in gt:
    marker='function render(){'
    premium_js=r'''function premiumPage(){const k=selected||'premium';const data={premium:{title:'Premium Hub',sub:'Commander premium systems, seasonal rewards, and bounded convenience services.',items:[['season_pass_01','Season Pass','Unlock the seasonal reward track and premium objectives.'],['officer_logistics','Logistics Officer','10% logistics modifier for 24 hours.'],['service_queue','Queue Priority Service','Reduce one active queue completion time by 15%.']]},store:{title:'Premium Store',sub:'Transparent catalogue with server-validated prices and atomic wallet settlement.',items:[['season_pass_01','Empire Season Pass','Seasonal reward track and premium objectives.'],['service_queue','Queue Priority Service','Bounded queue convenience service.'],['service_colony_scan','Colony Scan Packet','One additional validated telemetry report.']]},commander:{title:'Commander',sub:'Daily reward, season pass progression, and wallet state.',items:[['daily_claim','Daily premium claim','Claim 100 Dark Matter once every 24 hours.'],['season_pass_01','Activate Season Pass','Unlock seasonal progression.']]},'premium-officers':{title:'Premium Officers',sub:'Time-limited officers with explicit effects and expiry tracking.',items:[['officer_logistics','Logistics Officer','Construction and fleet logistics modifier.'],['officer_science','Science Officer','Research output modifier.']]},'premium-services':{title:'Premium Services',sub:'Bounded convenience services with auditable credits and cooldowns.',items:[['service_queue','Queue Priority Service','One queue speed activation.'],['service_colony_scan','Colony Scan Packet','One validated colony scan credit.']]}};const d=data[k]||data.premium;const dm=state.resources?.dark_matter??state.resources?.darkMatter??0;const cards=d.items.map(([key,name,desc])=>`<div class="panel premium-offer"><div><span class="panel-kicker">PREMIUM OFFER</span><h3>${esc(name)}</h3><p>${esc(desc)}</p></div><div class="premium-actions">${key==='daily_claim'?`<button class="button" data-action="premium_claim_daily" data-redirect="commander">Claim daily reward</button>`:`<button class="button" data-action="premium_activate" data-item="${esc(key)}" data-redirect="${esc(k)}">Activate</button><button class="button secondary" data-action="premium_purchase" data-item="${esc(key)}" data-redirect="${esc(k)}">Purchase</button>`}</div></div>`).join('');document.getElementById('content').innerHTML=`<div class="page premium-page"><div class="page-heading"><div><span class="eyebrow">PREMIUM SYSTEMS</span><h1>${esc(d.title)}</h1><p>${esc(d.sub)}</p></div><span class="badge good">SERVER VERIFIED</span></div><section class="metric-strip"><div class="metric"><span>Dark Matter</span><strong>${fmt(dm)}</strong><small>Premium wallet balance</small></div><div class="metric"><span>Season Pass</span><strong>${state.premium?.season_pass?'ACTIVE':'AVAILABLE'}</strong><small>Progression track</small></div><div class="metric"><span>Daily Claim</span><strong>100 DM</strong><small>24-hour cooldown</small></div><div class="metric"><span>Audit</span><strong>LOCKED</strong><small>Atomic transaction ledger</small></div></section><section class="premium-layout"><div><div class="section-heading"><span class="panel-kicker">CATALOGUE</span><h2>Premium controls</h2></div>${cards}</div><aside class="panel premium-contract"><span class="panel-kicker">SYSTEM DESIGN</span><h2>Server-authoritative premium economy</h2><p>Prices, rewards, cooldowns, ownership, and effect expiry are resolved on the server. The client submits only an item key and bounded intent.</p><div class="contract-row"><span>Wallet lock</span><b>FOR UPDATE</b></div><div class="contract-row"><span>Feedback</span><b>READY · COOLDOWN · ERROR</b></div><div class="contract-row"><span>Audit</span><b>GAME EVENTS</b></div></aside></section><section class="panel"><div class="panel-kicker">TRANSACTION HISTORY</div><h2>Recent premium activity</h2><p>Purchases and activations are persisted with player ownership and timestamps.</p><span class="badge">READ ONLY</span></section></div>`;bindPremiumButtons()}
function bindPremiumButtons(){document.querySelectorAll('[data-action^="premium_"]').forEach(b=>b.onclick=()=>{const action=b.dataset.action,payload={item_key:b.dataset.item||'',quantity:1};if(action==='premium_claim_daily')delete payload.item_key;submitIntent(action,b.dataset.redirect||selected,payload)})}
'''
    gt=gt.replace(marker,premium_js+marker)
    old="else if(selected==='messages')messagesPage();"
    new=old+"else if(['premium','store','commander','premium-officers','premium-services'].includes(selected))premiumPage();"
    gt=gt.replace(old,new)
g.write_text(gt)
